"""End-to-end tests through main.py with independent certificate verification."""
import json, subprocess, sys, random, time
sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace/tmp')
import verify
from gen2 import gen_case
from probability import window_thresholds
import numpy as np

def run_main(raw):
    p = subprocess.run([sys.executable, '-B', '/workspace/submission/main.py'],
                       input=raw, capture_output=True,
                       env={'PATH': '/usr/local/bin:/usr/bin:/bin',
                            'LD_LIBRARY_PATH': '/workspace/native',
                            'PYTHONPATH': '/workspace/vendor',
                            'PYTHONHASHSEED': '0'})
    return p.returncode, p.stdout, p.stderr

def check_case(case, res):
    J = len(case['windows'])
    if J:
        feats = np.array([w[7] for w in case['windows']], dtype=np.int64).reshape(J,9,2)
        preds = __import__('testcnnonnx' if case['model']=='cnn' else 'testrnnonnx').evaluate_model_single_pass(
            feats, np.zeros(J, dtype=np.int64))
    else:
        preds = []
    thresholds = window_thresholds(case['stats'], case['windows'])
    values = [case['windows'][j][6] * case['class_values'][preds[j]] for j in range(J)]
    errs = verify.verify(case, res, thresholds, values)
    if preds != res['predictions']:
        errs.append('predictions mismatch')
    if thresholds != res['thresholds']:
        errs.append('thresholds mismatch')
    # reports recomputation
    import metrics
    rep = metrics.selected_report(case['flows'], case['windows'], res['predictions'], res['assignment'])
    if json.dumps(rep, sort_keys=True) != json.dumps(res['reports'], sort_keys=True):
        errs.append('reports mismatch')
    return errs

def main():
    tests = []
    # edge cases
    tests.append(('empty-batch', {'version': 3, 'cases': []}))
    tests.append(('no-windows', {'version': 3, 'cases': [
        {'model': 'cnn', 'class_values': [1]*7, 'stats': [5, 7, 75], 'bucket': [3, 2],
         'slots': [[0, 2, 0]], 'flows': [[2, 3, -1, 1]], 'groups': [], 'windows': []}]}))
    tests.append(('all-gated-out', None))
    tests.append(('huge-times', None))
    tests.append(('zero-capacity', None))
    tests.append(('deep-groups', None))
    tests.append(('single-flow', None))
    tests.append(('ratio-one', None))
    # invalid inputs
    invalids = [
        b'{"version":3,"cases":[]}',
        b'{"version":2,"cases":[]}',
        b'{"version":3.0,"cases":[]}',
        b'{"version":3,"cases":{},"x":1}',
        b'{"version":3,"cases":[] } extra',
        b'{"version":3,"cases":[{"model":"cnn"}]}',
        b'{"version":3,"cases":[{"model":"cnn","class_values":[1,1,1,1,1,1,1],"stats":[1,1,1],"bucket":[1,1],"slots":[[0,1,1]],"flows":[[1,1,-1,0]],"groups":[],"windows":[]}]}',
        b'{"version":3,"cases":[{"model":"cnn","class_values":[1,1,1,1,1,1,1],"stats":[1,1,1],"bucket":[1,1],"slots":[[0,1,0],[0,1,0]],"flows":[[1,1,-1,0]],"groups":[],"windows":[]}]}',
        b'{"version":3,"cases":[{"model":"cnn","class_values":[1,1,1,1,1,1,1],"stats":[1,1,1],"bucket":[1,1],"slots":[[0,1,0]],"flows":[[1,1,-1,0]],"groups":[],"windows":[[0,0,0,0,1,0,1,[[0,0]]*9]]}]}',
        b'{"version":3,"cases":[{"model":"cnn","class_values":[1,1,1,1,1,1,1],"stats":[1,1,1],"bucket":[1,1],"slots":[[0,1,0]],"flows":[[1,1,-1,0]],"groups":[],"windows":[[0,0,0,1,1,0,1,[[0,0]]*9,[1,1]]]}]}',
        ('utf8bad', b'{"version":3,"cases":[]}\xff'),
        ('deep', ('{"version":3,"cases":[],"a":' + '['*70 + ']'*70 + '}').encode()),
    ]
    fails = 0
    for name, case in tests:
        if case is None:
            rng = random.Random(hash(name) & 0xffff)
            if name == 'all-gated-out':
                c = gen_case(rng, 6, 3, 2, 1)
                for w in c['windows']:
                    w[5] = 65535
                batch = {'version': 3, 'cases': [c]}
            elif name == 'huge-times':
                c = gen_case(rng, 8, 4, 3, 1)
                base = 10 ** 12
                for i, s in enumerate(c['slots']):
                    s[0] = base - 100 + i * 7
                for w in c['windows']:
                    w[1] = rng.randint(base - 100, base)
                    w[2] = min(base, w[1] + rng.randint(0, 20))
                batch = {'version': 3, 'cases': [c]}
            elif name == 'zero-capacity':
                c = gen_case(rng, 8, 4, 3, 1)
                for s in c['slots']:
                    s[1] = 0
                c['bucket'] = [4, 0]
                batch = {'version': 3, 'cases': [c]}
            elif name == 'deep-groups':
                c = gen_case(rng, 10, 4, 4, 8)
                for i, g in enumerate(c['groups']):
                    g[0] = i - 1 if i else -1
                    g[1] = 10
                for f in c['flows']:
                    f[2] = len(c['groups']) - 1 if f[2] >= 0 else -1
                batch = {'version': 3, 'cases': [c]}
            elif name == 'single-flow':
                c = gen_case(rng, 12, 5, 1, 0)
                batch = {'version': 3, 'cases': [c]}
            else:
                c = gen_case(rng, 8, 4, 2, 1)
                c['flows'][0][0] = 1
                c['flows'][0][1] = 1
                batch = {'version': 3, 'cases': [c]}
            case = batch['cases'][0]
            raw = json.dumps(batch).encode()
        else:
            raw = json.dumps(case).encode()
        code, out, err = run_main(raw)
        if code != 0:
            print(name, 'NONZERO', code, err[:200]); fails += 1; continue
        try:
            got = json.loads(out.decode())
        except Exception as exc:
            print(name, 'BAD JSON', exc, out[:200]); fails += 1; continue
        if set(got.keys()) != {'version', 'results'} or got['version'] != 3:
            print(name, 'BAD TOP', got); fails += 1; continue
        if len(got['results']) != 1:
            print(name, 'BAD LEN'); fails += 1; continue
        res = got['results'][0]
        fields = {'predictions','reports','ratio','thresholds','assignment','utility','age','flow','potential','cut'}
        if set(res.keys()) != fields:
            print(name, 'BAD FIELDS', set(res.keys()) ^ fields); fails += 1; continue
        errs = check_case(case, res)
        if errs:
            print(name, 'ERRORS', errs[:5]); fails += 1
        else:
            print(name, 'ok ratio', res['ratio'], 'util', res['utility'], 'age', res['age'])
    for name, raw in invalids:
        if isinstance(name, str) and not isinstance(raw, bytes):
            raw = name; name = 'raw'
        code, out, err = run_main(raw)
        ok = (code == 0 and out.strip() == b'{"error":"invalid"}')
        if not ok:
            print('INVALID', name, 'code', code, 'out', out[:120], err[:120]); fails += 1
        else:
            print('invalid', name, 'ok')
    print('FAILS', fails)
    return fails

if __name__ == '__main__':
    sys.exit(1 if main() else 0)
PYEOF
